import org.apache.nifi.annotation.behavior.EventDriven;
import org.apache.nifi.annotation.lifecycle.OnScheduled;
import org.apache.nifi.components.PropertyDescriptor;
import org.apache.nifi.flowfile.FlowFile;
import org.apache.nifi.processor.ProcessContext;
import org.apache.nifi.processor.ProcessSession;
import org.apache.nifi.processor.ProcessorInitializationContext;
import org.apache.nifi.processor.Relationship;
import org.apache.nifi.processor.util.StandardValidators;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

@EventDriven
public class MyCSVProcessor extends AbstractProcessor {

    public static final PropertyDescriptor INPUT_FILE = new PropertyDescriptor.Builder()
            .name("Input File")
            .description("Path to the input CSV file")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final Relationship REL_SUCCESS = new Relationship.Builder()
            .name("success")
            .description("Success relationship")
            .build();

    private List<PropertyDescriptor> descriptors;
    private Set<Relationship> relationships;

    @Override
    protected void init(final ProcessorInitializationContext context) {
        final List<PropertyDescriptor> descriptors = new ArrayList<>();
        descriptors.add(INPUT_FILE);
        this.descriptors = Collections.unmodifiableList(descriptors);

        final Set<Relationship> relationships = new HashSet<>();
        relationships.add(REL_SUCCESS);
        this.relationships = Collections.unmodifiableSet(relationships);
    }

    @Override
    public Set<Relationship> getRelationships() {
        return relationships;
    }

    @Override
    public List<PropertyDescriptor> getSupportedPropertyDescriptors() {
        return descriptors;
    }

    @OnScheduled
    public void onScheduled(final ProcessContext context) {
        // Initialization logic if needed
    }

    @Override
    public void onTrigger(final ProcessContext context, final ProcessSession session) throws ProcessException {
        FlowFile flowFile = session.create();
        if (flowFile == null) {
            return;
        }

        String inputFile = context.getProperty(INPUT_FILE).getValue();
        BufferedReader reader = null;
        try {
            reader = new BufferedReader(new InputStreamReader(session.read(flowFile)));
            String line;
            StringBuilder transformedData = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                // Perform transformation on each line
                String transformedLine = transform(line);
                transformedData.append(transformedLine).append("\n");
            }

            // Write transformed data back to the flow file
            flowFile = session.write(flowFile, out -> out.write(transformedData.toString().getBytes()));
            session.transfer(flowFile, REL_SUCCESS);
        } catch (Exception e) {
            getLogger().error("Failed to process CSV file", e);
            session.transfer(flowFile, REL_FAILURE);
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (Exception e) {
                    getLogger().error("Failed to close reader", e);
                }
            }
        }
    }

    private String transform(String line) {
