public class Integration {
    private static final Logger LOGGER = Logger.getLogger(Integration.class.getName());
    private static final int TIMEOUT = 300; // Timeout in milliseconds

    public void integrate() {
        // Start all services asynchronously with timeouts
        CompletableFuture<Void> service1Future = CompletableFuture.runAsync(this::callService1)
                .orTimeout(TIMEOUT, TimeUnit.MILLISECONDS)
                .exceptionally(ex -> {
                    handleException(ex, "Service1");
                    return null;
                });

        CompletableFuture<Void> service2Future = CompletableFuture.runAsync(this::callService2)
                .orTimeout(TIMEOUT, TimeUnit.MILLISECONDS)
                .exceptionally(ex -> {
                    handleException(ex, "Service2");
                    return null;
                });

        CompletableFuture<Void> service3Future = CompletableFuture.runAsync(this::callService3)
                .orTimeout(TIMEOUT, TimeUnit.MILLISECONDS)
                .exceptionally(ex -> {
                    handleException(ex, "Service3");
                    return null;
                });

        // Wait for all services to complete
        CompletableFuture.allOf(service1Future, service2Future, service3Future).join();
    }

    private void callService1() {
        Service1 service1 = new Service1();
        service1.call();
    }

    private void callService2() {
        Service2 service2 = new Service2();
        service2.call();
    }

    private void callService3() {
        Service3 service3 = new Service3();
        service3.call();
    }

    private void handleException(Throwable ex, String serviceName) {
        if (ex instanceof TimeoutException) {
            LOGGER.log(Level.WARNING, serviceName + " timed out after " + TIMEOUT + " ms.");
            // Handle timeout, e.g., fallback mechanism
        } else {
            LOGGER.log(Level.SEVERE, serviceName + " failed", ex);
        }
    }
}

